namespace PA.Tickets.Domain.Tickets;
public sealed class WorkItem
{
 public long Id{get;private set;} public long TicketId{get;private set;} public string Number{get;private set;}=""; public string PublicId{get;private set;}=""; public long? ToDepartmentId{get;private set;} public long? ToTeamId{get;private set;} public long? AssignedToUserId{get;private set;} public long? PriorityId{get;private set;} public string Status{get;private set;}="PENDING"; public string? WaitingFor{get;private set;} public string? WaitingComment{get;private set;} public string? WaitingEvidenceReference{get;private set;} public DateTimeOffset? WaitingExpectedDate{get;private set;} public DateTimeOffset? WaitingStartedAt{get;private set;} public DateTimeOffset? WaitingResumedAt{get;private set;} public int WaitingMinutes{get;private set;} public DateTimeOffset? StartedAt{get;private set;} public DateTimeOffset? CompletedAt{get;private set;}
 private WorkItem(){}
 public static WorkItem Create(long id,long ticketId,string number,long? departmentId,long? teamId,long actorUserId,long? priorityId=null,string? publicId=null){if(ticketId<=0||string.IsNullOrWhiteSpace(number))throw new ArgumentException("A work item requires a ticket and number.");return new(){Id=id,TicketId=ticketId,Number=number.Trim(),PublicId=publicId ?? string.Empty,ToDepartmentId=departmentId,ToTeamId=teamId,PriorityId=priorityId};}
 public bool Assign(long userId,DateTimeOffset now){if(userId<=0)throw new ArgumentException("Assignee is required.");var changed=AssignedToUserId!=userId;AssignedToUserId=userId;Status="ASSIGNED";StartedAt??=now;return changed;}
 public void Start(DateTimeOffset now){if(Status is "COMPLETED" or "CANCELLED")throw new InvalidOperationException("Completed or cancelled work cannot be started.");Status="IN_PROGRESS";StartedAt??=now;}
 public void Wait(string reason,string? comment,string? evidenceReference,DateTimeOffset? expectedDate,DateTimeOffset now){if(Status!="IN_PROGRESS")throw new InvalidOperationException("Only executing work can wait.");if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Waiting reason is required.");Status="WAITING";WaitingFor=reason.Trim();WaitingComment=comment?.Trim();WaitingEvidenceReference=evidenceReference?.Trim();WaitingExpectedDate=expectedDate;WaitingStartedAt=now;}
 public void Resume(DateTimeOffset now){if(Status!="WAITING")throw new InvalidOperationException("Only waiting work can resume.");if(WaitingStartedAt is null)throw new InvalidOperationException("Waiting start is missing.");WaitingResumedAt=now;WaitingMinutes+=(int)Math.Max(0,(now-WaitingStartedAt.Value).TotalMinutes);WaitingStartedAt=null;WaitingFor=null;Status="IN_PROGRESS";}
 public void Complete(DateTimeOffset now){if(Status!="IN_PROGRESS")throw new InvalidOperationException("Only executing work can be completed.");Status="COMPLETED";CompletedAt=now;}
 public void Cancel(DateTimeOffset now){if(Status=="COMPLETED")throw new InvalidOperationException("Completed work cannot be cancelled.");Status="CANCELLED";CompletedAt=now;}
 public static WorkItem Restore(long id,long ticketId,string number,long? departmentId,long? teamId,long? assignee,long? priorityId,string status,string? waitingFor,string? waitingComment,string? waitingEvidenceReference,DateTimeOffset? waitingExpectedDate,DateTimeOffset? waitingStarted,DateTimeOffset? waitingResumed,int waitingMinutes,DateTimeOffset? started,DateTimeOffset? completed,string? publicId=null)=>new(){Id=id,TicketId=ticketId,Number=number,PublicId=publicId ?? string.Empty,ToDepartmentId=departmentId,ToTeamId=teamId,AssignedToUserId=assignee,PriorityId=priorityId,Status=status,WaitingFor=waitingFor,WaitingComment=waitingComment,WaitingEvidenceReference=waitingEvidenceReference,WaitingExpectedDate=waitingExpectedDate,WaitingStartedAt=waitingStarted,WaitingResumedAt=waitingResumed,WaitingMinutes=waitingMinutes,StartedAt=started,CompletedAt=completed};
}
